// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the full read path for a single GET in this cache cluster.", "The app calls the smart client. The client hashes the key with CRC16 mod 16384 to get a slot and looks up the owner in its cached slot map. If the key is flagged hot, it first checks a small in-process L1 with a very short TTL, or reads from a replica. Otherwise it sends the GET to the slot's primary. A hit returns at once. A MOVED redirect makes the client refresh its slot map and retry. An ASK redirect sends a one-off retry to the importing node. On a miss, single-flight lets one caller per key load from the database, write the value with a jittered TTL, and serve the callers that were waiting. Throughout, the client records latency and the hit or miss for telemetry."),
    s(5, "What is the difference between a MOVED and an ASK redirect, and how should a client react to each?", "MOVED means the slot now belongs to another node permanently. The client should update its slot map, either for that slot or by refreshing the whole map with CLUSTER SHARDS, and then retry on the new owner. ASK appears only during a slot migration. It means this particular key has already moved to the importing node, but the slot itself has not been reassigned yet. The client sends ASKING followed by the command to the target node, just once, and does not change its slot map. Later requests for that slot still go to the old owner until migration ends and a MOVED shows up. If a client wrongly updates its map on ASK, it can send requests for keys that have not moved to the importing node, which will just redirect them back."),
    s(5, "The requirement says the cache must never serve data past its intended staleness. How do you actually guarantee that?", "First, make the bound explicit for each data type, for example 30 seconds for a product price. Every cached value gets a TTL no longer than that bound, and jitter only shortens the TTL, never lengthens it. The L1 TTL must also fit within the bound, counting time spent on replicas, so total staleness equals L1 TTL plus replication lag plus the shared cache TTL. Next, on writes, invalidate rather than wait for expiry, and use change-data-capture from the database binlog as a backstop for missed deletes. If you serve stale values during a stampede, store the original load time with the value and refuse anything older than the bound. Finally, alert on replication lag so replica reads cannot quietly break the budget."),
    s(5, "How do you detect hot keys and stop one key from saturating a shard?", "For detection, the client or a proxy samples requests and counts keys over a sliding window, for example with a count-min sketch, and marks keys above a threshold as hot. With an LFU policy, server-side tools such as redis-cli --hotkeys also work, but client sampling responds faster. For mitigation, hot keys are served from an in-process L1 with a TTL of a second or two, which removes most of the traffic before it reaches the network. For heavy reads you can also spread load across replicas, or split the key into N copies such as key#0 to key#7 placed on different slots, with clients picking a copy at random. Writes to a split key have to update or invalidate every copy. Hot status should be dynamic and expire on its own."),
    s(5, "In cache-aside, why do teams delete the cache entry after a database write instead of updating it, and what race remains?", "If two writers update the database and then each sets the cache, their cache writes can land in the opposite order to their database commits. The cache then holds the older value until TTL. Deleting the entry avoids that, because the next reader loads whatever is current. One race remains. A reader misses, reads the old value from the database, and pauses. Meanwhile a writer commits and deletes the key. The reader then writes the old value back. This is uncommon but real. Ways to reduce it include leases, where the server hands out a token on a miss and rejects the fill if a delete happened in between, version-checked sets, a short delayed second delete, and a TTL that caps how long the damage can last."),
    s(5, "A shard primary dies. Walk me through failover and tell me what data can be lost.", "Other nodes stop getting heartbeats. After the node timeout they mark the primary as possibly failed, and once a majority of primaries agree, it is marked failed. Its replicas wait a short delay based on replication offset, so the most up-to-date replica usually asks first, and they request votes. A replica that wins a majority of primaries is promoted, takes a higher config epoch, and announces the new ownership. Clients get MOVED replies or refresh their maps and then follow the new primary. Because replication is asynchronous, writes the old primary acknowledged but never sent to the replica are lost. For a cache that loss is usually fine. For write-back data it is not, which is why write-back needs a durable queue outside the cache."),
    s(4, "What is split-brain in a cache cluster, and how does the config epoch fence off a stale primary?", "Split-brain happens when a network partition leaves the old primary running on the minority side while the majority side promotes a replica. For a while, two nodes believe they own the same slots. Redis Cluster limits this in two ways. A primary that cannot reach a majority stops accepting writes after the node timeout, which caps how long it can diverge. Every ownership change also carries a config epoch, and when nodes see conflicting claims, the higher epoch wins. When the partition heals, the old primary sees the higher epoch, steps down to become a replica, and throws away the writes it took during the split. Clients that reach it get redirected. The remaining risk is the writes accepted during that short window."),
    s(4, "How do you protect the database from cache penetration, where requests ask for keys that do not exist?", "Missing keys always miss, so an attacker or a bug can push every one of these requests to the database. The first defence is negative caching. When the database returns nothing, cache a placeholder with a short TTL, and keep it short so a record created later shows up quickly. For large keyspaces, put a Bloom filter of valid IDs in front. A Bloom filter never gives a false negative, so a 'not present' answer can be rejected without touching the database. It does give occasional false positives, which simply go through to the database as normal. Add input validation such as ID format and range checks, plus per-client rate limits. Also alert on a rise in misses that return empty results."),
    s(5, "What happens if the whole cache cluster restarts cold or a huge batch of keys expires together, and how do you protect the database?", "That is a cache avalanche. Hit ratio drops to near zero and the full read load hits the database. Prevention starts with jittered TTLs, so keys loaded together do not expire together, and with replicas and persistence so one failure does not empty the cache. For the cold-start case, warm the cache from an RDB snapshot or by replaying a list of hot keys before taking traffic, and add nodes back gradually. At the database edge, put a concurrency limiter or circuit breaker in front of loads. Requests beyond the database's safe capacity get a stale value, a default, or a fast error rather than queuing. Single-flight still applies per key. The goal is to degrade gracefully, never to overload the database."),
    s(4, "Size a cluster for 200 million keys averaging 500 bytes and 1 million operations per second. State your assumptions.", "Raw data is 200 million times 500 bytes, about 100 GB. Per-key overhead from the key itself, dictionary entries and allocator waste is significant for small values, so I would assume 1.5 to 2 times raw, giving about 150 to 200 GB. Add headroom for fragmentation and copy-on-write during snapshots, and aim for around 60 to 70 percent memory use. That points to roughly 300 GB of primary memory, or about 12 shards of 25 GB. For throughput, I would benchmark one node with our value sizes and pipelining rather than assume a number. If a node safely handles about 100k ops per second, 1 million needs at least 10 primaries, so 12 works with margin. One replica per primary doubles memory. I would validate this with a load test."),
    s(4, "Why map keys to a fixed slot space instead of hashing them directly onto a ring of nodes?", "A fixed slot space separates key placement from node placement. The key-to-slot mapping never changes. Only slot ownership changes, and that is a small, explicit table that clients can cache and nodes can gossip. Moving load means reassigning specific slots, which is easy to reason about, migrate one at a time, and monitor. Balance is controlled directly, because you assign equal slot counts or move individual hot slots, instead of depending on where random virtual node points happen to fall. It also makes redirects simple, since a node knows exactly which slots it serves. The trade-offs are a fixed upper limit on how finely data can be split, 16384 in Redis Cluster, and the need to run something that decides slot assignment."),
    s(4, "How do multi-key operations work in a sharded cache, and what are the pitfalls of hash tags?", "Commands such as MGET, MULTI/EXEC transactions or Lua scripts that touch several keys only work when all keys hash to the same slot. Otherwise the server returns a CROSSSLOT error. Hash tags solve this. If a key contains braces, only the text inside them is hashed, so user:{42}:cart and user:{42}:profile land together. The pitfall is skew. If the tag has low cardinality, such as a tenant ID with one giant tenant, a whole tenant's data sits on one slot, creating hot shards and slots too large to migrate quickly. Use tags only for small, naturally grouped data. For wider reads, let the client split the keys by slot and send the requests in parallel instead of forcing everything onto one slot."),
    s(4, "What consistency trade-offs come with reading from replicas?", "Replicas trail the primary because replication is asynchronous, so a replica read can return a value that was just overwritten or deleted. That breaks read-your-writes. A user updates a profile, refreshes, and sees the old version. It also adds replication lag to the staleness budget. In Redis Cluster a client has to send READONLY on the replica connection to read there. I would use replica reads only for hot, read-heavy keys that tolerate a little staleness, monitor replication offset lag per replica, and have clients stop using a replica whose lag goes above the budget. For keys that need read-your-writes, route the writer's own reads to the primary for a short window after a write, or keep them on primary only."),
    s(3, "Why does the cache expire TTL keys both lazily and with an active sweep?", "Lazy expiry checks the TTL when a key is accessed and deletes it if it has expired, so an expired value is never returned and no background work is needed. On its own, though, keys that are never read again would sit in memory forever. The active sweep handles that. Several times a second, Redis samples keys from the set that have TTLs, deletes the expired ones, and repeats while a large share of the sample turns out expired, within a time budget so latency stays steady. Together they give correctness from the lazy check and memory reclamation from the sweep. Replicas do not expire keys on their own timer. They wait for deletes from the primary, though a read on a replica still reports an expired key as missing."),
    s(3, "Which maxmemory policy would you choose for this cache and why?", "For a pure cache where every key can be rebuilt from the database, I would pick allkeys-lfu or allkeys-lru. LFU keeps steady popular keys better when there are scans or one-off bursts. LRU suits workloads where recent use predicts the next access. volatile-* policies only evict keys that have a TTL, so if some keys lack one, the node can fill up and start rejecting writes. They make sense only when the same instance also holds keys that must never be evicted, which I would rather put on a separate cluster. noeviction is wrong for a cache, because writes fail with an out-of-memory error once memory is full. Whatever the choice, watch the eviction rate, because steady evictions of useful keys mean the cluster is too small."),
    s(4, "What is the big key problem and how do you handle it?", "A big key is a single value or collection that is very large, such as a multi-megabyte string or a hash with millions of fields. Command execution is effectively single-threaded per node, so reading, deleting, expiring or migrating such a key can block every other client on that shard and cause latency spikes. It also skews memory and network use and slows slot migration. To handle it, find big keys with scans such as redis-cli --bigkeys or MEMORY USAGE sampling, and set size limits in client libraries. Split large collections into buckets by sub-key hash, and paginate with HSCAN or SSCAN rather than full reads. Use UNLINK instead of DEL and enable lazy-free options so large frees happen in the background."),
    s(4, "In write-back mode, what happens if a node dies before flushing, and how would you design the flush path?", "If the cache is the only place holding dirty writes, losing the primary loses them, because replication is asynchronous. So write-back needs the write to be durable somewhere before the client gets an acknowledgment. Usually that means appending to a replicated log such as Kafka, or a Redis Stream with AOF fsync and replicas plus WAIT, and the cache update happens alongside. A flusher consumes the log in batches and applies idempotent upserts keyed by entity and version, so replays after a crash are safe. It commits offsets only after the database confirms. Monitor consumer lag as the measure of durability debt, and apply backpressure if it grows. Reads during the delay come from the cache, which is the newest copy."),
    s(4, "How do you keep the in-process L1 cache from serving stale data?", "The simplest control is a very short TTL, a second or two, kept inside the staleness budget, and only for keys flagged hot. That bounds staleness without any coordination. For tighter freshness, Redis server-assisted client-side caching helps. With CLIENT TRACKING, the server remembers which keys a client has read, or which prefixes in broadcast mode, and pushes an invalidation message when they change. On reconnect or a lost invalidation channel, the client must flush its whole L1, because it cannot know what it missed. Cap L1 by entry count or memory so it cannot hurt the application's heap. Never put sensitive per-user data in a shared process cache without scoping it by user."),
    s(4, "Single-flight coalesces requests within one process. What about 500 app servers all missing the same key?", "Local single-flight cuts it to one database load per server per key, so up to 500 loads, which may still be too many for a hot key. To coordinate across servers, use a short lock in the cache itself, SET key:lock token NX PX with a timeout of a few seconds. The winner loads and fills the value. The others briefly poll, or better, serve the previous value kept with a soft expiry. The lock must expire in case the winner crashes, and should be released only if the token matches. Memcache-style leases do the same thing and also stop stale sets. Combine this with early refresh so hot keys rarely miss in the first place. These locks are about efficiency, not correctness."),
    s(3, "Compare probabilistic early refresh with lock-based stampede protection.", "Lock-based protection reacts after the miss. One caller refreshes while the others wait or get a stale value, which adds a lock round trip and some waiting. Probabilistic early refresh, as in the XFetch approach, acts before expiry. On each read, a caller decides at random to recompute, with a probability that rises as the TTL approaches zero and with how long recomputation takes. Busy keys get refreshed by one caller just before expiry, so they effectively never miss, and no lock is needed. It needs the stored value to carry its compute time and expiry, and it may cause a few duplicate refreshes. In practice I combine them: early refresh for hot keys and a lock or single-flight as a backstop for real misses."),
    s(3, "Should a cache cluster use persistence such as RDB or AOF?", "For a pure cache, the database is the source of truth, so persistence exists only to avoid cold starts. RDB snapshots are a good fit. A restarted node loads a recent snapshot and comes back mostly warm, which protects the database. The cost is forking: copy-on-write can use up to the memory of pages changed during the snapshot, so you need headroom, and the fork itself can briefly stall large instances. AOF with fsync is for data you cannot lose, such as a write-back queue, and adds disk I/O and rewrite overhead. Without persistence, a node that restarts empty and is still a primary could replicate an empty dataset to its replicas, so either enable persistence or make sure restarted nodes come back as replicas."),
    s(4, "How would you secure this cache cluster?", "First, network isolation. Nodes live in private subnets, and security groups allow only app servers and other nodes on the client port and the cluster bus port. Never expose them to the internet. Turn on TLS for client and replication traffic, including the bus where supported. Use ACLs, available since Redis 6, so each service has its own user limited to its key prefixes and needed commands. Block dangerous commands such as FLUSHALL, KEYS, CONFIG and DEBUG for application users. Keep passwords in a secrets manager and rotate them. Keep protected mode on and disable the default user. Encrypt RDB and AOF files at rest. Log admin commands and authentication failures, and patch quickly, since remote-execution vulnerabilities have affected exposed instances."),
    s(3, "What privacy concerns arise when caching personal data, and how do you address them?", "Caches create extra copies of personal data, often outside the database's access controls and deletion processes. Under India's DPDP Act and similar laws, a deletion or correction request has to reach the cache too. So user-data keys need a predictable naming scheme, say user:{id}:*, that a deletion job can invalidate, plus a TTL so missed copies age out. Cache only the fields needed, and keep sensitive identifiers such as Aadhaar or card numbers out of it, or tokenize them. Separate tenants with ACL key prefixes or separate clusters. Encrypt snapshots, and restrict who can run MONITOR or read RDB files, since both expose values. Logs and telemetry should record key patterns, not values or raw user IDs."),
    s(4, "Which metrics and alerts would you set up for this cluster, and why?", "Per shard I track hit ratio, p99 latency, ops per second, memory used against maxmemory, evicted and expired keys, connected clients, CPU, network bytes, replication offset lag, and migration progress. From the client side I track miss rate per key prefix, MOVED and ASK rates, timeouts, and database load caused by misses. Alerts should catch trouble before the database feels it. Examples are a hit ratio falling below baseline for several minutes, one shard's traffic or CPU far above its peers, which signals a hot key, a rising eviction rate, replication lag above the staleness budget, memory above about 80 percent, and a migration that stalls. Dashboards should put database query rate next to the cache hit ratio so the link is obvious."),
    s(3, "Why replicate asynchronously instead of synchronously, and what does WAIT give you?", "Asynchronous replication keeps write latency at a single local operation. The primary acknowledges right away and streams changes in the background, which suits a latency-focused cache. Synchronous replication would add a network round trip to every write and couple primary availability to replica health. The cost is that acknowledged writes can be lost on failover. WAIT numreplicas timeout lets a client block until that many replicas have acknowledged its earlier writes, which lowers the chance of loss for selected operations. It does not give strong consistency. A failover can still promote a replica that did not receive the write, and WAIT does not roll back on timeout. Use it for important write-back records, not as a consensus protocol."),
    s(2, "What alternatives to ring-based consistent hashing exist, and when would you use them?", "Rendezvous hashing, also called highest random weight, scores each key against every node and picks the highest. It needs no ring or virtual nodes, balances well, and moves only the keys of a node that joins or leaves, but lookup cost grows with node count. Jump consistent hash maps a key to one of N numbered buckets with almost no memory and very even balance, but it only handles adding or removing the last bucket, so it suits numbered shards rather than arbitrary nodes. Maglev hashing builds a lookup table for fast, even mapping and is common in load balancers. For a cache with uneven nodes and planned migrations, an explicit slot table is usually the most practical choice."),
    s(3, "How should a smart client maintain its slot map without overloading the cluster?", "At startup the client fetches the topology from a seed node with CLUSTER SHARDS, or the older CLUSTER SLOTS, and caches it. It refreshes when it receives MOVED, when a connection fails, and on a slow periodic timer as a safety net. The risk is a refresh storm. During a failover, thousands of clients all get errors and all fetch topology at once. To prevent that, combine concurrent refreshes in each client so only one request is in flight, rate-limit refreshes to something like once per second, add jitter, and spread topology queries across several nodes. A single MOVED can update just that slot right away while a full refresh runs in the background. ASK never triggers a refresh."),
    s(3, "How would you extend this design across multiple regions?", "Usually each region runs its own independent cache cluster in front of its local database replica, because cross-region round trips would undo the latency benefit. The hard part is invalidation. A write in one region must invalidate cached copies everywhere. The common way is to drive invalidation from the database's change stream, so each region deletes keys after its local database replica has applied the change. That ordering avoids refilling from a lagging replica. The staleness budget then includes cross-region replication lag. Active-active cache replication with conflict resolution exists in some commercial products, but for a cache, independent clusters plus change-data-capture invalidation is simpler. Watch for one region's outage shifting its traffic onto another region's cold cache."),
    s(3, "How do you safely remove a node or replace a failed one?", "To remove a primary, first move all its slots to other primaries in small batches, using the same copy-then-switch migration as when adding a node, and watch hit ratio and database load as it goes. Once it owns no slots, move its replicas elsewhere and run CLUSTER FORGET on every node so the node is not gossiped back in. To replace a failed primary, rely on automatic failover first, then add a fresh node as a replica of the new primary so redundancy is restored. If a shard has lost all replicas, its data is gone, and the slots must be reassigned and rewarmed carefully. Never remove several nodes at once if the remaining memory cannot hold the working set."),
    s(3, "Would you build this on Redis or Memcached, and why?", "Memcached is simple and multi-threaded. It is very efficient for plain key-value strings, and sharding is done entirely in the client. It has no built-in replication, persistence or cluster-managed failover, so losing a node means losing its keys and taking a miss spike. Redis, or the open-source fork Valkey, has data structures, replication, cluster mode with slots and failover, Lua scripting, server-assisted client caching, and ACLs, which match this design's needs: replicated shards, redirects during migration, and atomic lock primitives. Memcached is a reasonable choice for a large, simple, read-heavy cache where losing a node is acceptable. For the requirements here I would choose Redis or Valkey, and check licensing and managed-service options for the organisation."),
  ],
  objective: [
    o(5, "How many hash slots does Redis Cluster divide the keyspace into?", ["1024","4096","16384","65536"], 2, "Redis Cluster maps every key to one of 16384 slots and assigns those slots to primaries."),
    o(4, "Which hash function does Redis Cluster use to compute a key's slot?", ["MurmurHash3","CRC16","SHA-1","xxHash"], 1, "The slot is CRC16 of the key, or of its hash tag, modulo 16384."),
    o(5, "For the key order:{user42}:items, what does Redis Cluster hash to find the slot?", ["The whole key","order","user42","items"], 2, "When a key contains a non-empty {...} section, only the text inside the first pair of braces is hashed."),
    o(5, "During slot migration a client receives an ASK redirect. What should it do?", ["Update its slot map and retry on the new node","Send ASKING then the command to the target node, without updating its slot map","Retry on the same node after a backoff","Fail the request back to the application"], 1, "ASK is a one-off redirect for a slot that is still migrating, so the slot map stays unchanged."),
    o(4, "What does a MOVED reply indicate?", ["The key has expired","The slot is permanently served by another node, so the client should update its map","The node is overloaded","The key is being migrated right now"], 1, "MOVED signals a lasting ownership change, so the client refreshes its slot mapping."),
    o(4, "What happens when an MGET in Redis Cluster includes keys that hash to different slots?", ["It is split across nodes automatically by the server","It returns a CROSSSLOT error","It returns only keys from the first slot","It runs more slowly but succeeds"], 1, "Multi-key commands require all keys to be in the same slot, otherwise the server rejects them with CROSSSLOT."),
    o(5, "By default, how does a Redis primary replicate writes to its replicas?", ["Synchronously with quorum acknowledgment","Asynchronously","Through two-phase commit","Only at snapshot time"], 1, "The primary acknowledges the client first and streams changes to replicas in the background."),
    o(4, "Which statement about the WAIT command is correct?", ["It makes Redis strongly consistent","It blocks until the given number of replicas have acknowledged earlier writes, but failover can still lose writes","It rolls back writes that time out","It waits for the AOF to be written to disk"], 1, "WAIT lowers the risk of data loss but is not consensus, since a replica that missed the write can still be promoted."),
    o(5, "Why add random jitter to cache TTLs?", ["To make eviction cheaper","To spread out expirations so many keys do not miss at the same moment","To encrypt keys","To improve hash distribution"], 1, "Jitter prevents keys loaded together from expiring together and hitting the database all at once."),
    o(4, "Briefly caching a placeholder for a key that does not exist in the database mainly defends against what?", ["Cache penetration","Hot keys","Replication lag","Memory fragmentation"], 0, "Negative caching stops repeated lookups of missing keys from always reaching the database."),
    o(3, "A Bloom filter of valid IDs is placed in front of the cache. Which property makes it safe to reject requests?", ["It has no false positives","It has no false negatives","It stores full values","It supports deletes natively"], 1, "If the filter says an ID is absent, it is definitely absent, while false positives just fall through to normal lookups."),
    o(4, "With maxmemory-policy set to noeviction, what happens when memory is full?", ["Least recently used keys are deleted","Commands that would use more memory return an error","The node restarts","Keys are moved to disk"], 1, "noeviction refuses writes that need memory and returns an out-of-memory error."),
    o(3, "Under volatile-lru, which keys can be evicted?", ["Any key","Only keys that have a TTL set","Only keys without a TTL","Only keys in hash tags"], 1, "volatile-* policies only consider keys with an expiry, so a cache full of keys without TTLs can fill up."),
    o(3, "Why is lazy expiry alone not enough?", ["It can return expired values","Expired keys that are never accessed again would never be freed","It blocks the event loop","It breaks replication"], 1, "The active sweep reclaims memory held by expired keys that no client reads again."),
    o(2, "By default, which port does the Redis Cluster bus use?", ["The data port plus 1","The data port plus 10000","Always 6380","A random port"], 1, "Nodes gossip and coordinate failover over the client port plus 10000, for example 16379, so firewalls must allow it."),
    o(3, "What must a client send on a connection to a replica before it can read from it in Redis Cluster?", ["ASKING","READONLY","REPLICAOF","CLIENT TRACKING"], 1, "Without READONLY, a replica redirects reads to its primary with MOVED."),
    o(4, "What is the main purpose of the config epoch in failover?", ["To count keys per slot","To settle conflicting slot ownership, where the higher epoch wins and stale primaries are fenced","To schedule snapshots","To encrypt the cluster bus"], 1, "A newly promoted replica takes a higher epoch, so after a partition the old primary sees it, steps down, and drops its writes."),
    o(5, "After a failover with asynchronous replication, what can happen to writes the old primary acknowledged?", ["They are always kept","Some may be lost if they had not reached the promoted replica","They are replayed from the client","They are rolled back in the database"], 1, "Async replication means the acknowledgment comes before replication, so the last moments of writes can be lost."),
    o(3, "In Redis Cluster, what does a primary on the minority side of a partition do?", ["Keeps accepting writes indefinitely","Stops accepting writes after the node timeout","Deletes all its data immediately","Promotes itself to a higher epoch"], 1, "This caps how long it can diverge from the majority side, which may have promoted a replica."),
    o(5, "In cache-aside with concurrent writers, why is deleting the cache key after the database commit usually safer than setting the new value?", ["Deletes are faster than sets","Sets from different writers can arrive out of order and leave an older value cached","Deletes are replicated synchronously","Sets do not support TTL"], 1, "Invalidation lets the next reader load the current committed value, so set ordering stops mattering."),
    o(4, "What does single-flight request coalescing achieve on a cache miss?", ["It guarantees strong consistency","It lets only one caller per key, per scope, load from the database while others wait or reuse the result","It replicates the value to all nodes","It evicts the key early"], 1, "Coalescing turns N simultaneous loads of the same key into one load."),
    o(3, "How does probabilistic early expiration (the XFetch approach) prevent stampedes?", ["It locks the key in the database","Readers randomly recompute before expiry, more often as expiry nears, so one refresh usually happens before the miss","It doubles every TTL","It blocks all readers until refresh finishes"], 1, "Spreading refresh decisions out over time means hot keys are renewed before they expire, without locks."),
    o(3, "Why does an RDB snapshot need spare memory on the node?", ["It compresses data in RAM","fork uses copy-on-write, so pages modified during the snapshot get duplicated","It loads the AOF at the same time","Replicas send their data back"], 1, "Under heavy writes, copy-on-write can come close to doubling memory for the pages that change."),
    o(4, "One product key receives a large share of all reads and saturates its shard. Which mitigation is most effective?", ["Increase the key's TTL","Serve it from a short-TTL in-process L1 cache or split it into several copies across slots","Move it to a hash tag","Switch to noeviction"], 1, "L1 caching and key splitting spread or absorb the load instead of sending it all to one primary."),
    o(4, "Roughly how much raw value data do 100 million keys at 1 KB each represent, before overhead?", ["About 1 GB","About 10 GB","About 100 GB","About 1 TB"], 2, "100,000,000 times 1 KB is about 100 GB, and real memory use is higher once per-key overhead and fragmentation are added."),
    o(3, "Which command frees a very large key without blocking the server while memory is reclaimed?", ["DEL","UNLINK","EXPIRE 0","FLUSHDB"], 1, "UNLINK removes the key from the keyspace right away and frees its memory in a background thread."),
    o(3, "Which Redis feature lets the server push invalidation messages for keys a client has cached locally?", ["Keyspace hashing","CLIENT TRACKING (server-assisted client-side caching)","MONITOR","CLUSTER SETSLOT"], 1, "With tracking turned on, the server remembers which keys a client read and notifies it when they change."),
    o(4, "Which is the best way to restrict an application to its own key prefix and a safe set of commands?", ["Rename the cluster","Create an ACL user with key patterns and an allowed command list","Turn off persistence","Use hash tags"], 1, "Redis ACLs, available since version 6, control per-user command categories and key patterns."),
    o(4, "While one slot is being moved to a new node, which keys can see extra misses or redirects?", ["All keys in the cluster","Only keys in the slot being moved","Only keys that have TTLs","Only keys on replicas"], 1, "Moving slots a few at a time limits disruption to the fraction of data in those slots."),
    o(5, "The hit ratio drops sharply while database QPS rises on one dashboard. What is the most likely immediate concern?", ["A healthy cache warm-up with no risk","Misses are passing through to the database, which could cause an overload","Replication is too fast","Too few clients are connected"], 1, "A falling hit ratio sends more load directly to the database, so it should trigger an alert before the database fails."),
  ],
};
export default bank;
